const item = $input.first()?.json || {};
const text = (item.command || item.body?.message?.text || '').trim();
const senderId = item.sender_id || item.body?.message?.from?.id;
const chatId = item.chat_id || item.body?.message?.chat?.id;
const parts = text.split(/\s+/);
const cmd = parts[0].toLowerCase();
const targetChatId = parts[1] ? parts[1].replace(/[^0-9-]/g, '') : null;

let action = 'UNKNOWN';
let query = '';

if (cmd === '/on') {
  action = 'ENABLE_GLOBAL';
  query = `UPDATE agent_control_state SET is_enabled = true, updated_by = ${senderId || 0}, updated_at = NOW() WHERE id = 1 RETURNING is_enabled;`;
} else if (cmd === '/off') {
  action = 'DISABLE_GLOBAL';
  query = `UPDATE agent_control_state SET is_enabled = false, updated_by = ${senderId || 0}, updated_at = NOW() WHERE id = 1 RETURNING is_enabled;`;
} else if (cmd === '/status') {
  action = 'GET_STATUS';
  query = `SELECT is_enabled, sleep_mode_enabled, updated_at FROM agent_control_state WHERE id = 1; SELECT chat_id, pause_reason, updated_at FROM chat_conversation_state WHERE is_paused = true;`;
} else if (cmd === '/pause' && targetChatId) {
  action = 'PAUSE_CHAT';
  query = `INSERT INTO chat_conversation_state (chat_id, is_paused, last_message_from, pause_reason, updated_at) VALUES (${targetChatId}, true, 'seller', 'Manual owner pause', NOW()) ON CONFLICT (chat_id) DO UPDATE SET is_paused = true, pause_reason = 'Manual owner pause', updated_at = NOW() RETURNING chat_id;`;
} else if (cmd === '/resume' && targetChatId) {
  action = 'RESUME_CHAT';
  query = `INSERT INTO chat_conversation_state (chat_id, is_paused, last_message_from, pause_reason, updated_at) VALUES (${targetChatId}, false, 'seller', 'Manual owner resume', NOW()) ON CONFLICT (chat_id) DO UPDATE SET is_paused = false, pause_reason = 'Resumed by owner', updated_at = NOW() RETURNING chat_id;`;
}

return {
  cmd,
  action,
  targetChatId,
  query,
  chat_id: chatId,
  sender_id: senderId
};

const cmdInfo = $('Parse Owner Command').first().json;
const action = cmdInfo.action;
const chat_id = cmdInfo.chat_id;
let message = '';

if (action === 'ENABLE_GLOBAL') {
  message = '✅ [AI Sales Agent]: Automation has been ENABLED globally.\n\nThe AI will now automatically process and reply to eligible customer inquiries in your personal Telegram DMs.';
} else if (action === 'DISABLE_GLOBAL') {
  message = '🛑 [AI Sales Agent]: Automation has been DISABLED globally.\n\nAll automated replies are suspended until explicitly re-enabled via /on.';
} else if (action === 'PAUSE_CHAT') {
  message = `⏸️ [Chat Paused]: Customer chat ${cmdInfo.targetChatId} is now PAUSED.\n\nThe AI will not respond to this customer until you issue /resume ${cmdInfo.targetChatId}.`;
} else if (action === 'RESUME_CHAT') {
  message = `▶️ [Chat Resumed]: Customer chat ${cmdInfo.targetChatId} is now RESUMED.\n\nThe AI will handle automated inquiries for this customer again.`;
} else if (action === 'GET_STATUS') {
  const results = $input.all().map(i => i.json);
  const state = results[0] || { is_enabled: false };
  const statusText = state.is_enabled ? '🟢 ENABLED' : '🔴 DISABLED';
  message = `📊 [AI Sales Agent Status]\n• Global Automation: ${statusText}\n• Timezone: Asia/Manila (PHT, UTC+8)\n• Last Updated: ${state.updated_at || 'Never'}\n\nCommands:\n/on — Enable AI\n/off — Disable AI\n/status — Refresh status\n/pause <chat_id> — Pause customer\n/resume <chat_id> — Resume customer`;
} else {
  message = '⚠️ Unknown command. Supported commands: /on, /off, /status, /pause <chat_id>, /resume <chat_id>';
}

return {
  chat_id,
  reply_text: message
};

